      <StepIndicator steps={defaultSteps} initialStep={1} onStepChange={() => {}} />
    )
    // Check that step 2 button has active styling (color purple)
    const step2 = screen.getByText('Step 2').closest('button')
    expect(step2).toHaveStyle({ color: 'purple.400' })
  })

  it('calls onStepChange when a future step is clicked', async () => {
