    const handleChange = vi.fn()
    render(
      <StepIndicator
        steps={defaultSteps}
        disabled
        onStepChange={handleChange}
      />
    )
    const step2 = screen.getByText('Step 2').closest('button')
    await userEvent.click(step2!)
    expect(handleChange).not.toHaveBeenCalled()
  })

  it('renders with navigation role and aria-label', () => {
    render(<StepIndicator steps={defaultSteps} onStepChange={() => {}} />)
    const nav = screen.getByRole('navigation')
    expect(nav).toHaveAttribute('aria-label', 'Progress steps')
